const previousCommonBinding = bindCommon;
const originalLabMarkup = labMarkup;
const originalLabBinding = bindLab;
let bookState = {index:0,playing:false,speed:1400,inspected:null}, bookTimer=null;
const freeLabs = new Set();
function sketchPerson(name='Maya',thought=false){return `<svg class="sketch-person" viewBox="0 0 110 160" role="img" aria-label="${name}, your curious learning companion"><path d="M36 45C15 23 41 1 62 8C83 3 104 28 83 50" fill="#24231f"/><path d="M34 35q-2 38 23 42q28-3 28-42" fill="#f1dfc4" stroke="#25241e" stroke-width="2.2"/><path d="M34 33q18 0 24-14q9 16 28 17" fill="#25241e"/><circle cx="47" cy="44" r="2.5"/><circle cx="70" cy="44" r="2.5"/><path d="M59 48l-3 9h6m-12 6q10 8 20-1" fill="none" stroke="#25241e" stroke-width="1.6" stroke-linecap="round"/><path d="M43 76l-21 56h68L75 76z" fill="${thought?'#d7e6d4':'#f5ce53'}" stroke="#25241e" stroke-width="2.2"/><path d="M27 96L8 80m78 19 15-35" fill="none" stroke="#25241e" stroke-width="3" stroke-linecap="round"/><path d="M36 134l-4 23m44-23 8 23" stroke="#25241e" stroke-width="4"/><text x="56" y="113" text-anchor="middle" font-family="monospace" font-size="16">${thought?'?':'aha!'}</text></svg>`}
function pencilArrow(){return `<svg viewBox="0 0 160 50" aria-hidden="true"><path d="M7 26q72-37 128-1m-14-15 17 16-23 8" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/></svg>`}
layout = function(content,view){return `<div class="menu-scrim" id="menuScrim"></div><aside class="sidebar book-drawer" id="sidebar"><div class="drawer-title"><span class="scribble">Your book of ideas</span><button id="closeDrawer" aria-label="Close contents">×</button></div><nav class="side-nav" aria-label="Main navigation">${[['home','⌂','The first page'],['course','▤','Table of contents'],['playground','✳','Animation studio'],['journey','⚑','My discoveries'],['cheatsheet','▧','Revision notes']].map(([id,icon,label])=>`<a href="#${id}" class="${view===id?'active':''}"><span class="nav-icon">${icon}</span>${label}</a>`).join('')}</nav><span class="side-label">CHAPTERS</span><nav class="chapter-nav" aria-label="Chapters">${chapterInfo.map((c,i)=>`<a href="#course/${i}"><span>${String(i+1).padStart(2,'0')}</span>${c[0]}<em>${topics.filter(t=>t.chapter===i).length}</em></a>`).join('')}</nav><div class="side-bottom"><div class="progress-card"><strong>Ideas you made your own</strong><div class="progress-track"><span style="width:${percent()}%"></span></div><span class="muted">${progress.mastered.length} / ${topics.length} lessons</span></div></div></aside><div class="shell"><header class="topbar notebook-top"><div class="row"><button class="mobile-menu" id="menuButton" aria-label="Open contents" aria-expanded="false">☰</button><a class="book-brand" href="#home"><span class="brand-stamp">ODOO</span><span>fieldnotes<small>A VISUAL LEARNING ADVENTURE</small></span></a></div><nav class="book-nav" aria-label="Book navigation"><a href="#course" class="${['course','lesson'].includes(view)?'active':''}">The chapters</a><a href="#playground" class="${view==='playground'?'active':''}">Let’s play</a><a href="#journey" class="${view==='journey'?'active':''}">My discoveries</a></nav><div class="top-actions"><button id="openSearch" class="search-trigger" aria-label="Find a topic">⌕ <span>Find an idea</span><span class="key">⌘ K</span></button><span class="xp">✦ ${xp()}</span></div></header><main id="main" class="main notebook-main" tabindex="-1">${content}<footer class="footer"><span>100 ideas. A curious brain. A pencil is optional.</span><span>Original stories & illustrations · ${storageAvailable?'Progress saved in this browser':'Progress lasts for this session'}</span></footer></main></div>`};
home = function(){let next=topics.find(t=>t.id===progress.last)||topics[0];return `<div class="book-kicker"><span>THE VISUAL GUIDE TO DATA STRUCTURES & ALGORITHMS</span><span class="scribble">for the “wait… why?” kind of mind ↙</span></div><section class="notebook-hero"><div class="hero-copy"><span class="yellow-tape">Engineering ideas. Everyday stories.</span><h1>Your brain called.<br>It wants <span class="ink-underline">pictures.</span></h1><p>Arrays are toy shelves. Stacks are pancakes.<br>Recursion? A set of nesting dolls.<br><strong>You know more DSA than you think.</strong></p><div class="row"><a class="btn primary" href="#lesson/${progress.visited.length?next.id:'stacks'}">${progress.visited.length?'Pick up where you left off':'Show me the pancake story'} →</a><a class="text-link" href="#course">Flip through all 100 topics ↗</a></div><div class="hero-pencil-note">See it. Predict it. Try it. <span>Then it sticks.</span>${pencilArrow()}</div></div><div class="hero-scrap"><div class="torn-label">Exhibit A: the pancake problem</div><div class="pancake-scene" id="homePancakeScene"><svg id="homePancakeSvg" viewBox="0 0 420 280" role="img" aria-label="An interactive stack of pancakes"></svg><div class="hand-note top-note">last one on<br>first one off ↙</div><div class="home-person">${sketchPerson('Maya',true)}</div><div class="speech-small">So… this is<br>a <strong>STACK?</strong></div></div><div class="pancake-controls"><button class="btn" id="addPancake">+ Add a pancake</button><button class="btn primary" id="eatPancake">Eat the top one ↑</button></div><p id="pancakeCaption" class="scribble" role="status">Go on. Play with your food.</p><span class="stamp-note">NO MEMORIZATION REQUIRED</span></div></section><div class="notebook-divider"><span>Here’s how we get the idea into your head</span></div><section class="learn-method"><article><span class="scribble method-number">01.</span><h3>Meet a familiar problem.</h3><p>A story you can picture, with a curious friend asking the questions you’re thinking.</p></article><article><span class="scribble method-number">02.</span><h3>Make a little prediction.</h3><p>Step through a topic-specific animation. Rewind. Inspect. Watch the “why” unfold.</p></article><article><span class="scribble method-number">03.</span><h3>Give your brain a workout.</h3><p>Arrange the steps, challenge a misconception, and explain the idea in your own words.</p></article></section><div class="section-head book-contents-head"><div><span class="scribble red-note">There’s a whole adventure in here ↓</span><h2>The book of “aha!” moments</h2><p>100 topics, from your first array to advanced algorithms.</p></div><a class="text-link" href="#course">Open the contents →</a></div><section class="book-chapters">${chapterInfo.map((c,i)=>`<a class="book-chapter" href="#course/${i}"><span class="chapter-big">${String(i+1).padStart(2,'0')}</span><div><h3>${c[0]}</h3><p>${c[1]}</p><span class="chapter-preview">${topics.filter(t=>t.chapter===i).slice(0,3).map(t=>t.title).join(' · ')}…</span></div><span class="scribble">${topics.filter(t=>t.chapter===i).length} ideas ↗</span></a>`).join('')}</section><div class="sticky-question"><span class="scribble">What if I’m a total beginner?</span><p>Good. Start with a toy room. We’ll build the technical words after the idea makes sense.</p><a class="text-link" href="#lesson/foundations">Open page one →</a></div>`};
function boardMarkup(t){return `<section class="animation-board" data-topic="${t.id}"><div class="board-heading"><span class="scribble">See what happens ↓</span><span class="board-label">${storyboards[t.id].title}</span><button class="board-reset" id="bookReset" aria-label="Restart animation">↺</button></div><div class="stage-wrap"><svg id="storyStage" viewBox="0 0 760 255" role="img" aria-label="Worked animation for ${esc(t.title)}"></svg><span class="stage-note">tap an object to inspect it</span></div><div class="board-explanation"><span class="bubble-person">${sketchPerson('Byte')}</span><p id="boardSay" aria-live="polite"></p></div><div id="objectInspector" class="object-inspector" hidden></div><div class="board-controls"><button class="btn" id="bookPrev">← Back</button><button class="btn primary" id="bookPlay">Play the story ▷</button><button class="btn" id="bookNext">Next move →</button><label class="speed-control">Pace <select id="bookSpeed"><option value="2200">Slow & thoughtful</option><option value="1400" selected>Just right</option><option value="700">Quick recap</option></select></label><span id="frameCount" class="scribble"></span></div><label class="visually-hidden" for="bookScrub">Animation frame</label><input id="bookScrub" class="book-scrub" type="range" min="0" max="${storyboards[t.id].frames.length-1}" value="0"><div id="boardPrediction" class="prediction-panel"><span class="scribble red-note">Before your brain switches off…</span><strong>${t.question}</strong><div class="prediction-options">${t.answers.map((a,i)=>`<button data-predict="${i}">${esc(a)}</button>`).join('')}</div><p id="predictionFeedback" role="status"></p></div></section>`}
function wordHighlight(text){return esc(text).replace(/\b(O\([^)]*\)|LIFO|FIFO|root|prefix|stack|queue|recursion|vertices|edges|state|sorted|children|pivot|hash|invariant|subsequence|subproblems)\b/gi,'<mark>$1</mark>')}
lesson = function(t){const i=topics.indexOf(t),next=topics[i+1],marked=progress.bookmarks.includes(t.id);return `<article class="book-lesson"><div class="page-margin-note scribble">Chapter ${String(t.chapter+1).padStart(2,'0')}<br>page ${String(i+1).padStart(3,'0')} / 100</div><div class="lesson-top"><a class="text-link" href="#course/${t.chapter}">← Back to ${chapterInfo[t.chapter][0]}</a><button class="btn plain" id="bookmark">${marked?'★ Saved in my book':'☆ Save this page'}</button><button class="btn plain" id="focusToggle">Focus view ◉</button></div><header class="book-lesson-title"><span class="yellow-tape">${t.analogy}</span><h1>${t.title}<span class="scribble title-doodle">?!</span></h1><p>Forget the intimidating name for a moment. Let’s begin with something you know.</p></header><section class="story-comic" id="story"><div class="comic-character">${sketchPerson('Maya',true)}<span class="scribble">Maya</span></div><div class="comic-story"><span class="scribble">Picture this…</span><p>${t.story}</p></div><div class="comic-reply"><span class="scribble">“Okay, but what<br>does that have to<br>do with business?”</span>${pencilArrow()}<span class="tiny-pill">A VERY GOOD QUESTION</span></div></section><section id="experiment" class="lesson-section"><div class="section-head"><div><span class="eyebrow">DON’T JUST READ IT</span><h2>Let the idea move.</h2></div><span class="scribble">Your hands are part<br>of the lesson. ↙</span></div>${boardMarkup(t)}</section><section class="lesson-section connect-section" id="idea"><div class="connect-copy"><span class="scribble red-note">Connect the dots.</span><h2>That thing you just saw?<br>Here’s its real name.</h2><p>${wordHighlight(t.meaning)}</p></div><aside class="sticky-note"><span class="scribble">Explain it to a<br>5-year-old:</span><p>${t.analogy}.</p><p>${t.steps[0]}</p><button id="walkStep" class="text-link">And then? →</button><p id="walkText" role="status">Tap to walk through all three moves.</p></aside></section><section class="lesson-section" id="workout"><div class="section-head"><div><span class="scribble">Pencils out. Brains on.</span><h2>Put the moves in order.</h2><p>Drag the scraps, or tap their ↑ and ↓ buttons. Then check your reasoning.</p></div><span class="workout-stamp">BRAIN<br>WORKOUT</span></div><div class="order-workout"><div id="orderPieces"></div><div class="row"><button class="btn primary" id="checkOrder">Does my plan make sense? ✓</button><button class="btn" id="shuffleOrder">Mix the scraps ↺</button></div><p id="orderFeedback" role="status"></p></div></section><section class="lesson-section engineer-scraps" id="engineer"><div class="engineering-paper"><span class="scribble">Now, put your consultant hat on.</span><h2>When would I actually use this?</h2><p>${t.use}</p><div class="cost-note"><strong>Evidence to inspect</strong><p>${t.cost}</p></div></div><button class="trap-card" id="trapReveal" aria-expanded="false"><span class="scribble red-note">Wait… there’s a catch.</span><span class="trap-symbol">!</span><strong>One small mistake can change the whole answer.</strong><span class="trap-hint">Tap to uncover the pitfall ↗</span><span id="trapText" hidden>${t.trap}</span></button></section><section class="lesson-section" id="code"><div class="section-head"><div><span class="scribble">The idea, as a functional walkthrough.</span><h2>The practical path through Odoo.</h2></div></div><div class="code-card"><div class="code-head"><span>FUNCTIONAL WALKTHROUGH</span><button id="copyCode">Copy checklist ⧉</button></div><pre><code>${esc(t.code)}</code></pre></div><p class="muted">Menu starting points are guidance. Exact labels and availability depend on version, edition, installed apps, localization, settings, and your role. Use a training database.</p>${freeLabs.has(t.id)?`<details class="free-lab"><summary class="scribble">Want to change the inputs? Open the experiment bench →</summary><p class="muted">Try your own small changes. The visual story above is a worked example.</p>${originalLabMarkup(t)}</details>`:''}</section><section class="lesson-section" id="check"><div class="section-head"><div><span class="scribble">A little retrieval makes a big difference.</span><h2>What did your brain keep?</h2><p>Three checks. Useful feedback. As many retries as you need.</p></div></div><div id="quiz">${quizMarkup(t)}</div></section><section class="lesson-section" id="practice"><div class="remember-card"><div><span class="scribble">Look away. Can you explain it?</span><h3>${t.analogy}</h3><p>Try telling the story without looking. How does it connect to ${t.title.toLowerCase()}?</p><button class="btn" id="flipMemory">Flip for a reminder ↺</button></div><div id="memoryBack" hidden><span class="scribble">The three little moves</span><ol>${t.steps.map(s=>`<li>${s}</li>`).join('')}</ol></div></div></section><section class="lesson-section notes-paper"><label for="notes" class="scribble">Your own “aha!” goes here.</label><textarea class="notes" id="notes" placeholder="I used to think… Now I picture…">${esc(progress.notes[t.id]||'')}</textarea><p class="muted" id="noteStatus">Private notes, saved in this browser.</p></section><div class="next-lesson">${i?`<a class="text-link" href="#lesson/${topics[i-1].id}">← Previous page</a>`:'<span></span>'}${next?`<a class="btn primary" href="#lesson/${next.id}">Turn the page: ${next.title} →</a>`:'<a class="btn primary" href="#journey">Look at everything you learned →</a>'}</div></article>`};
function positionItems(board,frame,W=760){
 const n=frame.items.length,kind=board.kind,mobile=W<500;
 if(kind==='tree')return frame.items.map((v,i)=>{let d=Math.floor(Math.log2(i+1)),start=2**d-1,j=i-start;return{x:W*(j+1)/(2**d+1),y:45+d*80,w:mobile?Math.min(78,W/(2**d+1)-8):90,h:mobile?58:45}});
 if(kind==='stack')return frame.items.map((v,i)=>({x:W/2,y:215-i*48,w:150,h:38}));
 if(kind==='ring')return frame.items.map((v,i)=>({x:W/2+Math.min(135,W*.3)*Math.cos(i/n*2*Math.PI-Math.PI/2),y:130+85*Math.sin(i/n*2*Math.PI-Math.PI/2),w:mobile?65:78,h:45}));
 if(kind==='graph'){const ps=[[W*.12,135],[W*.36,50],[W*.36,225],[W*.67,50],[W*.67,225],[W*.88,135]];return frame.items.map((v,i)=>({x:ps[i%6][0],y:ps[i%6][1],w:mobile?Math.min(80,W*.21):100,h:mobile?65:55}))}
 let cards=['cards','timeline','bars'].includes(kind);
 let cols=kind==='grid'?Math.round(Math.sqrt(n)):mobile?Math.min(n,cards?2:4):n>6?Math.ceil(n/2):n;
 const rows=Math.ceil(n/cols),w=Math.min(cards?195:95,(W-35)/cols-12);
 return frame.items.map((v,i)=>({x:W/2+(i%cols-(cols-1)/2)*(w+12),y:rows===1?125:55+Math.floor(i/cols)*78,w,h:cards?65:48}));
}
function drawBoard(t){const b=storyboards[t.id],f=b.frames[bookState.index],svg=$('#storyStage');const previous=new Map([...svg.querySelectorAll('[data-object]')].map(g=>[g.dataset.object,{x:+g.dataset.x,y:+g.dataset.y}]));let W=Math.max(300,Math.min(760,svg.clientWidth||760));let p=positionItems(b,f,W);svg.setAttribute('viewBox',`0 0 ${W} ${Math.max(255,...p.map(q=>q.y+65))}`);const keys=f.items.map((v,i)=>v+'-'+f.items.slice(0,i).filter(x=>x===v).length);let lines='';const edge=(i,j,label='',directed=false)=>{if(!p[i]||!p[j]||f.items[i]==='∅'||f.items[j]==='∅')return '';let u=p[i],v=p[j],active=f.active.includes(i)&&f.active.includes(j);return `<g class="story-edge ${active?'edge-active':''}"><path d="M${u.x} ${u.y}L${v.x} ${v.y}" ${directed?'marker-end="url(#arrowPen)"':''}/>${label?`<text x="${(u.x+v.x)/2}" y="${(u.y+v.y)/2-10}" text-anchor="middle">${esc(label)}</text>`:''}</g>`};if(b.kind==='tree')for(let i=1;i<f.items.length;i++)lines+=edge(Math.floor((i-1)/2),i);if(['chain','double','queue'].includes(b.kind))for(let i=1;i<f.items.length;i++)lines+=edge(i-1,i,'',true);if(b.kind==='ring')for(let i=0;i<f.items.length;i++)lines+=edge(i,(i+1)%f.items.length,'',true);if(b.kind==='graph'&&bookState.index===0||b.kind==='graph'&&f.items.length===b.frames[0].items.length)for(let e of b.edges)lines+=edge(...e);
svg.innerHTML=`<defs><marker id="arrowPen" markerWidth="7" markerHeight="7" refX="10" refY="3.5" orient="auto-start-reverse"><path d="M0 0L7 3.5L0 7" fill="none" stroke="#454139"/></marker></defs>${lines}${f.items.map((v,i)=>{if(v==='∅')return '';let q=p[i],active=f.active.includes(i),words=v.split(' '),multiline=v.length>16,parts=multiline?wrapText(v,Math.max(11,Math.floor(q.w/7))):[v];return `<g data-object="${esc(keys[i])}" data-index="${i}" data-x="${q.x}" data-y="${q.y}" role="button" tabindex="0" aria-label="Inspect ${esc(v)}" class="story-object ${active?'object-active':''}" transform="translate(${q.x} ${q.y})"><rect x="${-q.w/2}" y="${-q.h/2}" width="${q.w}" height="${q.h}" rx="${b.kind==='tree'||b.kind==='graph'?20:3}"/><text text-anchor="middle" y="${-(parts.length-1)*8+5}">${parts.slice(0,3).map((s,j)=>`<tspan x="0" dy="${j?16:0}">${esc(s)}</tspan>`).join('')}</text>${['array','grid'].includes(b.kind)?`<text class="item-index" y="${q.h/2+20}" text-anchor="middle">${b.kind==='grid'?`(${Math.floor(i/Math.round(Math.sqrt(f.items.length)))},${i%Math.round(Math.sqrt(f.items.length))})`:'['+i+']'}</text>`:''}${active?`<path class="pointer-doodle" d="M-10 ${-q.h/2-19}l10 11 10-11"/>`:''}</g>`}).join('')}`;
if(!matchMedia('(prefers-reduced-motion: reduce)').matches){svg.querySelectorAll('[data-object]').forEach(g=>{const old=previous.get(g.dataset.object);if(old){g.animate([{transform:`translate(${old.x}px,${old.y}px)`},{transform:`translate(${g.dataset.x}px,${g.dataset.y}px)`}],{duration:500,easing:'cubic-bezier(.2,.7,.2,1)'})}else g.animate([{opacity:0},{opacity:1}],{duration:400})})}
$('#boardSay').textContent=f.say;$('#frameCount').textContent=(bookState.index+1)+' / '+b.frames.length;$('#bookScrub').value=bookState.index;$('#bookPrev').disabled=bookState.index===0;$('#bookNext').disabled=bookState.index===b.frames.length-1;$('#bookPlay').textContent=bookState.playing?'Pause the story Ⅱ':bookState.index===b.frames.length-1?'Watch it again ↺':'Play the story ▷';$('#objectInspector').hidden=true;
const inspect=g=>{const i=+g.dataset.index;$('#objectInspector').hidden=false;$('#objectInspector').textContent=`You selected “${f.items[i]}” at snapshot position ${i}. ${f.active.includes(i)?'This is part of the current move.':'This item gives context for the current move.'} ${f.say}`;svg.querySelectorAll('.inspected').forEach(x=>x.classList.remove('inspected'));g.classList.add('inspected')};svg.querySelectorAll('[data-object]').forEach(g=>{g.onclick=()=>inspect(g);g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();inspect(g)}}});}
function wrapText(text,width){let words=text.split(' '),out=[],line='';for(let w of words){if(line&&(line+' '+w).length>width){out.push(line);line=w}else line+=(line?' ':'')+w}if(line)out.push(line);return out}
function stopBook(){clearInterval(bookTimer);bookTimer=null;bookState.playing=false}
function animateBook(t){stopBook();if(bookState.index===storyboards[t.id].frames.length-1)bookState.index=0;bookState.playing=true;drawBoard(t);bookTimer=setInterval(()=>{bookState.index++;if(bookState.index>=storyboards[t.id].frames.length-1)stopBook();drawBoard(t)},bookState.speed)}
function bindBoard(t){stopBook();bookState={index:0,playing:false,speed:1400,inspected:null};drawBoard(t);$('#bookNext').onclick=()=>{stopBook();bookState.index=Math.min(bookState.index+1,storyboards[t.id].frames.length-1);drawBoard(t)};$('#bookPrev').onclick=()=>{stopBook();bookState.index=Math.max(0,bookState.index-1);drawBoard(t)};$('#bookPlay').onclick=()=>bookState.playing?(stopBook(),drawBoard(t)):animateBook(t);$('#bookReset').onclick=()=>{stopBook();bookState.index=0;drawBoard(t)};$('#bookScrub').oninput=e=>{stopBook();bookState.index=+e.target.value;drawBoard(t)};$('#bookSpeed').onchange=e=>{const running=bookState.playing;bookState.speed=+e.target.value;if(running)animateBook(t)};document.querySelectorAll('[data-predict]').forEach(btn=>btn.onclick=()=>{let correct=+btn.dataset.predict===t.answer;btn.classList.remove('prediction-wrong','prediction-correct');btn.classList.add(correct?'prediction-correct':'prediction-wrong');$('#predictionFeedback').textContent=(correct?'Yes! ':'A useful wrong turn. ')+t.reason})}
let orderState=[];
function bindOrder(t){let dragIndex=null;function render(){ $('#orderPieces').innerHTML=orderState.map((n,i)=>`<div class="order-piece" draggable="true" data-order="${i}"><span class="scrap-grip" aria-hidden="true">⠿</span><b>${i+1}</b><span>${esc(t.steps[n])}</span><div><button data-move="up" data-position="${i}" aria-label="Move step ${i+1} up" ${i===0?'disabled':''}>↑</button><button data-move="down" data-position="${i}" aria-label="Move step ${i+1} down" ${i===2?'disabled':''}>↓</button></div></div>`).join('');$('#orderPieces').querySelectorAll('[data-order]').forEach(el=>{el.ondragstart=e=>{dragIndex=+el.dataset.order;e.dataTransfer.setData('text/plain',String(dragIndex));e.dataTransfer.effectAllowed='move';el.classList.add('dragging')};el.ondragend=()=>{dragIndex=null;el.classList.remove('dragging')};el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();let to=+el.dataset.order;if(dragIndex===null)return;const [n]=orderState.splice(dragIndex,1);orderState.splice(to,0,n);dragIndex=null;render();$('#orderFeedback').textContent='Moved a scrap. Check whether the dependencies make sense.'}});$('#orderPieces').querySelectorAll('[data-move]').forEach(btn=>btn.onclick=()=>{let i=+btn.dataset.position,j=i+(btn.dataset.move==='up'?-1:1);[orderState[i],orderState[j]]=[orderState[j],orderState[i]];render();$('#orderFeedback').textContent='Moved a scrap. Your reasoning matters.'})}function mix(){orderState=[1,2,0];render();$('#orderFeedback').textContent='The scraps are mixed up. What should happen first?'}mix();$('#shuffleOrder').onclick=mix;$('#checkOrder').onclick=()=>{const correct=orderState.every((n,i)=>n===i);$('#orderFeedback').textContent=correct?'✓ Your plan makes sense! '+t.steps.join(' '):'Not quite yet. Start with: '+t.steps[0]+' Think about what that makes possible next.';$('#orderFeedback').className=correct?'order-correct':'order-retry';if(correct)toast('You put the idea together ✦')};}
function pancakeSVG(count){return `<ellipse cx="210" cy="226" rx="122" ry="20" fill="#fffef7" stroke="#2d2922" stroke-width="2"/><ellipse cx="210" cy="226" rx="105" ry="13" fill="none" stroke="#c7bba5" stroke-width="1"/>${Array.from({length:count},(_,i)=>{let y=213-i*28;return `<g class="pancake-drawing" style="--p:${i}"><path d="M111 ${y-11}q99-38 198 0v14q-99 38-198 0Z" fill="${i===count-1?'#edbf6b':'#e6c799'}" stroke="#332c20" stroke-width="2"/><ellipse cx="210" cy="${y-11}" rx="99" ry="21" fill="#f6d595" stroke="#332c20" stroke-width="2"/><path d="M143 ${y-16}q36-12 70-5m27 2 26 4" fill="none" stroke="#b68947" stroke-width="1.2"/>${i===count-1?`<path d="M197 ${y-18}l26-5 11 11-25 6Z" fill="#fae875" stroke="#7a653d"/>`:''}<text x="112" y="${y+5}" font-family="Caveat, cursive" font-size="17" fill="#342c22">${String.fromCharCode(65+i)}</text></g>`}).join('')}<path d="M321 ${count?213-(count-1)*28-11:180}h31l-10-6m10 6-10 6" fill="none" stroke="#cf4c32" stroke-width="2"/>`}
function bindHomePancakes(){let count=3;$('#homePancakeSvg').innerHTML=pancakeSVG(count);const update=(delta)=>{let old=count;count=Math.max(0,Math.min(5,count+delta));$('#homePancakeSvg').innerHTML=pancakeSVG(count);$('#pancakeCaption').textContent=old===count?(count===0?'An empty stack has nothing left to pop.':'Five pancakes is enough for this little experiment.'):(delta>0?`Push ${String.fromCharCode(65+count-1)}. It becomes the new top.`:`Pop ${String.fromCharCode(65+count)}. The last one added leaves first.`);};$('#addPancake').onclick=()=>update(1);$('#eatPancake').onclick=()=>update(-1)}
bindCommon = function(){previousCommonBinding();if($('#closeDrawer'))$('#closeDrawer').onclick=()=>{$('#sidebar').classList.remove('open');$('#menuScrim').classList.remove('open');$('#menuButton').setAttribute('aria-expanded','false')};if($('#homePancakeSvg'))bindHomePancakes();$('.skip').onclick=e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView()}};
bindLab = function(t){if($('#storyStage'))bindBoard(t);if($('.free-lab .lab'))originalLabBinding(t)};
bindLesson = function(t){previousLessonBinding(t);bindOrder(t);$('#trapReveal').onclick=()=>{const open=$('#trapText').hidden;$('#trapText').hidden=!open;$('#trapReveal').setAttribute('aria-expanded',String(open));$('.trap-hint').textContent=open?'Tap to hide the pitfall ↙':'Tap to uncover the pitfall ↗'};$('#flipMemory').onclick=()=>{let back=$('#memoryBack');back.hidden=!back.hidden;$('#flipMemory').textContent=back.hidden?'Flip for a reminder ↺':'Try recalling it again ↺'}};
playground = function(id){const t=topics.find(t=>t.id===id)||topics[0];currentTopic=t;return `<div class="page-intro"><span class="yellow-tape">The animation studio</span><h1>“Wait… do that again.”</h1><p>One worked story for every topic. Play, pause, rewind, or tap any object to inspect the current move.</p></div><label class="scribble" for="labPicker">Pick an idea to play with:</label><select class="lab-picker" id="labPicker">${chapterInfo.map((c,i)=>`<optgroup label="${c[0]}">${topics.filter(x=>x.chapter===i).map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${x.title}</option>`).join('')}</optgroup>`).join('')}</select>${boardMarkup(t)}<div class="studio-footer"><span class="scribble">Want the story behind the moving parts?</span><a class="btn primary" href="#lesson/${t.id}">Open ${t.title} →</a></div>`};
const priorQuizQuestions=quizQuestions;
quizQuestions=function(t){
 const questions=priorQuizQuestions(t);
 const b=storyboards[t.id],correct=b.frames.at(-1).say;
 const candidates=topics.filter(x=>x.id!==t.id&&storyboards[x.id].frames.at(-1).say!==correct);
 const distractors=[candidates[(topics.indexOf(t)+3)%candidates.length],candidates[(topics.indexOf(t)+17)%candidates.length]].map(x=>storyboards[x.id].frames.at(-1).say);
 const values=[correct,...distractors],offset=(topics.indexOf(t)+1)%3;
 questions[1]={question:'Which outcome does this page’s worked animation demonstrate?',answers:values.slice(offset).concat(values.slice(0,offset)),answer:(3-offset)%3,reason:correct};
 return questions;
};
const notebookRoute=route;
route = function(){stopBook();notebookRoute();document.title=(currentTopic?currentTopic.title:'A visual learning adventure')+' — Odoo Functional fieldnotes';};
window.removeEventListener('hashchange',notebookRoute);
window.addEventListener('hashchange',route);
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#sidebar')?.classList.contains('open')){$('#sidebar').classList.remove('open');$('#menuScrim').classList.remove('open');$('#menuButton').setAttribute('aria-expanded','false');$('#menuButton').focus()}});
window.addEventListener('resize',()=>{if($('#storyStage')&&currentTopic)drawBoard(currentTopic)});
route();
